  "n2947": {"q":"解析怎麼說明正解？","o":["中午（太陽最高的時候）——太陽越高，影子越短", "早上太陽位置低，影子被拉得長；中午太陽最高，影子最短", "上午 10 點太陽還沒升到最高，影子比中午長", "清晨和傍晚太陽位置最低，影子被拉得最長"],"a":2},
  "n2948": {"q":"解析說其他選項各錯在哪？","o":["兩者都會隨太陽位置改變", "光源遠離影子才變小；只要有不透光物體就會有影子；影子不會變成彩色", "身高不會改變；水氣與地面溫度都不會改變影子長度", "風、地溫、竿子高度都不會讓影子轉方向"],"a":3},
  "n2949": {"q":"解析標出的課綱重點是什麼？","o":["影子長度的變化規律", "影子的日變化", "影子的變化", "光源位置與影子的關係"],"a":0},
  "n2950": {"q":"解析怎麼說明正解？","o":["太陽的位置愈高，影子愈短——高度角是太陽和地平線的夾角", "中午——太陽升到一天中最高的位置，影子也最短", "夏天中午太陽升得更高，影子比冬天中午更短", "上午影子漸短、中午最短、下午又漸長，正是一天的變化規律"],"a":1},
