  "n3729": {"q":"解析標出的課綱重點是什麼？","o":["槓桿的三要素", "槓桿的應用", "槓桿的平衡", "省力槓桿"],"a":0},
  "n3730": {"q":"解析怎麼說明正解？","o":["支點——槓桿有支點、施力點、抗力點三個要素", "施力點離支點越遠越省力——力臂越長越省力", "剪刀——剪刀是兩支槓桿組合而成，中間的軸就是支點", "力的大小和它到支點的距離都會影響槓桿的平衡——力小但距離遠，一樣可以平衡"],"a":1},
  "n3731": {"q":"解析說其他選項各錯在哪？","o":["施力點是出力的地方；抗力點是負載所在；沒有「中心點」這個專有名稱", "水杯、毛巾、窗簾都沒有繞支點轉動的省力構造", "2 個會變成 16 太重；4、8 個更重", "只看重量無法解釋這個現象"],"a":2},
  "n3732": {"q":"解析標出的課綱重點是什麼？","o":["槓桿的三要素", "槓桿的應用", "槓桿的平衡", "費力槓桿的用途"],"a":3},
  "n3733": {"q":"解析怎麼說明正解？","o":["雖然費力，但能靈活控制、夾取小東西，換來的是精準和速度——省力不是唯一的考量", "支點——槓桿有支點、施力點、抗力點三個要素", "剪刀——剪刀是兩支槓桿組合而成，中間的軸就是支點", "力的大小和它到支點的距離都會影響槓桿的平衡——力小但距離遠，一樣可以平衡"],"a":0},
  "n3734": {"q":"解析說其他選項各錯在哪？","o":["施力點是出力的地方；抗力點是負載所在；沒有「中心點」這個專有名稱", "天平不靠磁力、浮力或彈力（彈簧秤才靠彈力）", "水杯、毛巾、窗簾都沒有繞支點轉動的省力構造", "只看重量無法解釋這個現象"],"a":1},
  "n3735": {"q":"解析怎麼說明正解？","o":["支點——槓桿有支點、施力點、抗力點三個要素", "剪刀——剪刀是兩支槓桿組合而成，中間的軸就是支點", "要平衡不只看力的大小，還要看施力點離支點的距離——力小的一邊坐遠一點，就能和力大的一邊平衡", "力的大小和它到支點的距離都會影響槓桿的平衡——力小但距離遠，一樣可以平衡"],"a":2},
  "n3736": {"q":"解析怎麼說明正解？","o":["支點——槓桿有支點、施力點、抗力點三個要素", "剪刀——剪刀是兩支槓桿組合而成，中間的軸就是支點", "力的大小和它到支點的距離都會影響槓桿的平衡——力小但距離遠，一樣可以平衡", "只要槓桿夠長、支點位置適當，理論上再重的東西也能被撬起——強調槓桿原理的威力"],"a":3},
